// ❌ OLD: Pre-Boot, you manually wired every infrastructure bean.
// Even with H2 on the classpath, nothing happened until you wrote
// this configuration — repetitive, error-prone, and duplicated across
// every project.
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import javax.sql.DataSource;

@Configuration
public class DbConfigLegacy {
  @Bean
  DataSource dataSource() { // ❌ OLD: hand-created every time
    return new DriverManagerDataSource("jdbc:h2:mem:test", "sa", "");
  }
}
